import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.CeYlivdO.js";const p=JSON.parse('{"title":"Dynamic allocation problem","description":"Analyzing embedded dynamic memory issues","frontmatter":{"chapter":5,"cpp_standard":[11,14,17,20],"description":"Analyzing embedded dynamic memory issues","difficulty":"intermediate","order":1,"platform":"stm32f1","prerequisites":["Chapter 3: 内存与对象管理"],"reading_time_minutes":6,"tags":["cpp-modern","intermediate","stm32f1"],"title":"Dynamic allocation problem"},"headers":[],"relativePath":"en/vol8-domains/embedded/01-dynamic-allocation-issues.md","filePath":"en/vol8-domains/embedded/01-dynamic-allocation-issues.md","lastUpdated":null}'),s={name:"en/vol8-domains/embedded/01-dynamic-allocation-issues.md"};function o(l,e,r,c,d,m){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="the-cost-of-dynamic-memory-fragmentation-and-non-determinism-memory-layout-fragmentation-and-memory-alignment" tabindex="-1">The Cost of Dynamic Memory: Fragmentation and Non-Determinism (Memory Layout, Fragmentation, and Memory Alignment) <a class="header-anchor" href="#the-cost-of-dynamic-memory-fragmentation-and-non-determinism-memory-layout-fragmentation-and-memory-alignment" aria-label="Permalink to &quot;The Cost of Dynamic Memory: Fragmentation and Non-Determinism (Memory Layout, Fragmentation, and Memory Alignment)&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>In embedded systems, dynamic memory seems convenient, but its costs are often underestimated—fragmentation, timing non-determinism, and issues with alignment and structure padding can quietly consume resources and reliability.</p><p>As we all know, embedded environments have extremely limited resources, and minor memory allocation decisions can affect stability, real-time performance, and power consumption. Understanding the cost of dynamic memory helps us avoid catastrophic design errors—or at least minimize the risks when dynamic memory is unavoidable.</p><hr><h2 id="a-quick-review-of-memory-layout-static-heap-and-stack" tabindex="-1">A Quick Review of Memory Layout: Static, Heap, and Stack <a class="header-anchor" href="#a-quick-review-of-memory-layout-static-heap-and-stack" aria-label="Permalink to &quot;A Quick Review of Memory Layout: Static, Heap, and Stack&quot;">​</a></h2><p>Before we begin, let&#39;s review the core concepts:</p><ul><li><strong>Static area (.data/.bss/.rodata)</strong>: Sizes are determined at compile time or link time; holds global variables, constants, and read-only data. Their lifetime matches that of the program, the risk of fragmentation is nearly zero, but flexibility is low.</li><li><strong>Stack</strong>: Holds local variables and automatic objects for function calls. Allocation/deallocation is extremely fast (usually just pointer increments/decrements), highly structured, and lifetimes are controlled by scope. The downsides are limited capacity, inability to share across tasks, and unsuitability for large objects or objects with variable lifetimes.</li><li><strong>Heap</strong>: Dynamically allocated at runtime (<code>malloc</code> / <code>new</code> / <code>operator new</code>, etc.). Flexible but with obvious costs: allocation and deallocation times are non-deterministic, it generates fragmentation, and the memory layout is non-linear.</li></ul><p>In embedded development, the general order of preference is: stack (if size permits) → static (pre-allocated) → heap (use cautiously, ideally controlled).</p><hr><h2 id="fragmentation-what-why-and-how-it-affects-the-system" tabindex="-1">Fragmentation: What, Why, and How It Affects the System <a class="header-anchor" href="#fragmentation-what-why-and-how-it-affects-the-system" aria-label="Permalink to &quot;Fragmentation: What, Why, and How It Affects the System&quot;">​</a></h2><h3 id="internal-fragmentation" tabindex="-1">Internal Fragmentation <a class="header-anchor" href="#internal-fragmentation" aria-label="Permalink to &quot;Internal Fragmentation&quot;">​</a></h3><p>When an allocator allocates a larger block than actually requested to satisfy alignment or minimum allocation unit requirements, this unused space is <strong>internal fragmentation</strong>. Examples:</p><ul><li>If an allocator allocates in 16-byte granularity, a 20-byte object will occupy 32 bytes (16×2), and the extra 12 bytes become internal fragmentation.</li><li>Frequent allocation of small objects with a large allocation unit leads to decreased memory utilization.</li></ul><h3 id="external-fragmentation" tabindex="-1">External Fragmentation <a class="header-anchor" href="#external-fragmentation" aria-label="Permalink to &quot;External Fragmentation&quot;">​</a></h3><p>The heap contains many free blocks, but these blocks are scattered and non-contiguous, making it impossible to merge them into a large enough contiguous space to satisfy a larger allocation request. The result can be a situation where the total memory is sufficient, but allocation still fails (&quot;usable memory fragmentation&quot;). What we observe is—</p><ul><li>As runtime increases, available large blocks of memory decrease, leading to occasional <code>new</code>/<code>malloc</code> failures.</li><li>The system exhibits intermittent crashes, memory leak-like symptoms, and degraded stability after long-term operation.</li><li>Real-time tasks experience long-tail latency (sporadic long allocation/deallocation operations).</li></ul><hr><h2 id="alignment-and-padding" tabindex="-1">Alignment and Padding <a class="header-anchor" href="#alignment-and-padding" aria-label="Permalink to &quot;Alignment and Padding&quot;">​</a></h2><h3 id="why-alignment-is-needed" tabindex="-1">Why Alignment Is Needed <a class="header-anchor" href="#why-alignment-is-needed" aria-label="Permalink to &quot;Why Alignment Is Needed&quot;">​</a></h3><p>CPUs typically expect certain data to be aligned to its natural boundary (for example, 4-byte alignment, 8-byte alignment); otherwise, access becomes slower or triggers hardware exceptions on some architectures. Alignment also affects DMA, peripheral access, and cache coherency.</p><h3 id="structure-padding-example" tabindex="-1">Structure Padding Example <a class="header-anchor" href="#structure-padding-example" aria-label="Permalink to &quot;Structure Padding Example&quot;">​</a></h3><div class="language-cpp vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 假设：sizeof(char)=1, sizeof(int32_t)=4</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> A</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    char</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> c;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      // offset 0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    int32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // 如果按照 4 字节对齐，x 的 offset 通常是 4</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              // sizeof(A) 通常是 8（包括 3 字节填充）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><code>char</code> takes 1 byte, <code>int32_t</code> requires 4-byte alignment, so the compiler inserts 3 bytes of padding after <code>c</code>, aligning the total struct size to a multiple of 4 (which is 8 here).</p><p>Placing members with larger alignment requirements first can reduce padding:</p><div class="language-cpp vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> B</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    int32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    char</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> c;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // sizeof(B) 通常是 8，但如果有更多小成员，将更紧凑</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Alternatively, we can use <code>#pragma pack</code> or <code>__attribute__((packed))</code> to forcibly remove padding, but note:</p><ul><li>After removing padding, reading unaligned members can cause severe performance degradation or hardware exceptions on certain architectures.</li><li>Only use this when the consequences are fully understood and it is strictly necessary to save space.</li></ul><h4 id="relationship-with-dma-cachelines" tabindex="-1">Relationship with DMA / Cachelines <a class="header-anchor" href="#relationship-with-dma-cachelines" aria-label="Permalink to &quot;Relationship with DMA / Cachelines&quot;">​</a></h4><ul><li>DMA requires buffers to be aligned to peripheral requirements (for example, 32 bytes). Misalignment can cause hardware rejection or severe performance degradation.</li><li>Aligning to a cacheline (typically 32/64 bytes) helps avoid false sharing and cache thrashing, which is especially important in multi-core environments or when concurrently accessing memory with DMA.</li></ul><hr><h2 id="the-non-determinism-of-dynamic-memory-time-and-repeatability-issues" tabindex="-1">The Non-Determinism of Dynamic Memory: Time and Repeatability Issues <a class="header-anchor" href="#the-non-determinism-of-dynamic-memory-time-and-repeatability-issues" aria-label="Permalink to &quot;The Non-Determinism of Dynamic Memory: Time and Repeatability Issues&quot;">​</a></h2><ul><li><strong>Non-deterministic allocation/deallocation time</strong>: General-purpose heap implementations rely on complex data structures (free lists, trees, bitmaps), making the execution time of <code>malloc</code>/<code>free</code> unpredictable, potentially with long-tail latency.</li><li><strong>Concurrency and lock contention</strong>: In multi-threaded environments, the heap usually requires locks or thread-local caches (TLC); lock contention impacts real-time performance.</li><li><strong>Irrecoverable fragmentation</strong>: For standard C/C++ heaps, once fragmentation forms, it is difficult to recover in linear time. It must be resolved by restarting or using specialized compaction strategies (which are usually impractical).</li></ul><p>Embedded systems are particularly sensitive to this: long-tail latency can lead to dropped frames, control timeouts, or safety issues.</p><hr><h2 id="common-embedded-alternatives-and-hybrid-strategies" tabindex="-1">Common Embedded Alternatives and Hybrid Strategies <a class="header-anchor" href="#common-embedded-alternatives-and-hybrid-strategies" aria-label="Permalink to &quot;Common Embedded Alternatives and Hybrid Strategies&quot;">​</a></h2><p>So what do we do? Let&#39;s quickly go over a few common strategies:</p><h4 id="memory-pool-slab" tabindex="-1">Memory Pool / Slab <a class="header-anchor" href="#memory-pool-slab" aria-label="Permalink to &quot;Memory Pool / Slab&quot;">​</a></h4><ul><li>Divides memory into fixed-size blocks (for example, 32B, 64B, 256B). Allocation returns a block index or pointer, and deallocation returns the block to a free linked list.</li><li>Pros: Allocation/deallocation in constant time (O(1)), no external fragmentation (as long as all object sizes match a specific pool).</li><li>Cons: Requires multiple pools for different sized objects, memory utilization depends on allocation granularity, and it generates internal fragmentation.</li></ul><h4 id="bump-arena-allocator-linear-allocator" tabindex="-1">Bump / Arena Allocator (Linear Allocator) <a class="header-anchor" href="#bump-arena-allocator-linear-allocator" aria-label="Permalink to &quot;Bump / Arena Allocator (Linear Allocator)&quot;">​</a></h4><ul><li>Allocates linearly from a contiguous buffer; deallocation is usually all-at-once (resetting the entire arena).</li><li>Extremely fast with no fragmentation; suitable for objects with consistent lifetimes (for example, temporary objects during a single task or initialization phase).</li><li>Not suitable for objects that require arbitrary deallocation.</li></ul><h4 id="slab-allocation-linux-style" tabindex="-1">Slab Allocation (Linux Style) <a class="header-anchor" href="#slab-allocation-linux-style" aria-label="Permalink to &quot;Slab Allocation (Linux Style)&quot;">​</a></h4><ul><li>Suitable for caching identical types of objects (kernel objects); can reuse initialized objects upon deallocation, reducing construction/destruction overhead.</li></ul><h4 id="object-pool-raii-c-style" tabindex="-1">Object Pool + RAII (C++ Style) <a class="header-anchor" href="#object-pool-raii-c-style" aria-label="Permalink to &quot;Object Pool + RAII (C++ Style)&quot;">​</a></h4><ul><li>Combines a memory pool with <code>std::unique_ptr&lt;T, Deleter&gt;</code> or custom smart pointers to guarantee exception safety and automatic deallocation.</li></ul><hr><h2 id="code-examples" tabindex="-1">Code Examples <a class="header-anchor" href="#code-examples" aria-label="Permalink to &quot;Code Examples&quot;">​</a></h2>`,47)])])}const u=a(s,[["render",o]]);export{p as __pageData,u as default};
